import React from 'react';

export default function PortfolioCard({ item, onSelect }) {
	return (
		<div className="portfolio-card">
			<img src={item.acf.project_image.url} alt={item.title.rendered} />
			<h3>
				<button className="portfolio-title" onClick={() => onSelect(item)}>
					{item.title.rendered}
				</button>
			</h3>
		</div>
	);
}
