import React, { useState, useEffect } from 'react';
import PortfolioList from './components/PortfolioList';
import SearchBar from './components/SearchBar';
import FilterDropdown from './components/FilterDropdown';
import SortDropdown from './components/SortDropdown';
import Pagination from './components/Pagination';
import PortfolioModal from './components/PortfolioModal';

export default function BlockApp() {
	const [portfolioItems, setPortfolioItems] = useState([]);
	const [filteredItems, setFilteredItems] = useState([]);
	const [searchQuery, setSearchQuery] = useState("");
	const [selectedCategory, setSelectedCategory] = useState("");
	const [sortOption, setSortOption] = useState("date");
	const [selectedProject, setSelectedProject] = useState(null);
	const [currentPage, setCurrentPage] = useState(1);
	const itemsPerPage = 6;

	useEffect(() => {
		fetch(`/wp-json/wp/v2/portfolio?acf_format=standard&per_page=100`)
			.then(response => response.json())
			.then(data => {
				setPortfolioItems(data);
				setFilteredItems(data);
			});
	}, []);


	useEffect(() => {
		let updatedList = portfolioItems.filter(item =>
			item.title.rendered.toLowerCase().includes(searchQuery.toLowerCase()) ||
			(item.acf?.technology_used && item.acf.technology_used.toLowerCase().includes(searchQuery.toLowerCase()))
		);

		if (selectedCategory) {
			updatedList = updatedList.filter(item => item.acf?.category === selectedCategory);
		}

		if (sortOption === "alphabetical") {
			updatedList.sort((a, b) => a.title.rendered.localeCompare(b.title.rendered));
		} else {
			updatedList.sort((a, b) => new Date(b.date) - new Date(a.date));
		}

		setFilteredItems(updatedList);
	}, [searchQuery, selectedCategory, sortOption, portfolioItems]);


	const indexOfLastItem = currentPage * itemsPerPage;
	const indexOfFirstItem = indexOfLastItem - itemsPerPage;
	const currentItems = filteredItems.slice(indexOfFirstItem, indexOfLastItem);

	return (
		<div className="portfolio-showcase">
			<SearchBar searchQuery={searchQuery} setSearchQuery={setSearchQuery} />
			<FilterDropdown selectedCategory={selectedCategory} setSelectedCategory={setSelectedCategory} />
			<SortDropdown sortOption={sortOption} setSortOption={setSortOption} />
			<PortfolioList items={currentItems} onSelect={setSelectedProject} />
			<Pagination totalItems={filteredItems.length} itemsPerPage={itemsPerPage} currentPage={currentPage} setCurrentPage={setCurrentPage} />
			{selectedProject && <PortfolioModal project={selectedProject} onClose={() => setSelectedProject(null)} />}
		</div>
	);
}
