import React from 'react';

export default function PortfolioModal({ project, onClose }) {
	return (
		<div className="portfolio-modal" onClick={onClose}>
			<div className="modal-content" onClick={(e) => e.stopPropagation()}>
				<button className="close-modal" onClick={onClose}>&times;</button>
				<h2>{project.title.rendered}</h2>
				<p>{project.acf.project_description}</p>
				<a href={project.acf.project_url} target="_blank" rel="noopener noreferrer">
					View Project
				</a>
			</div>
		</div>
	);
}
